def transform(grid):
    g=[row[:] for row in grid]
    h,w=len(g),len(g[0])
    cells=[(r,c) for r in range(h) for c in range(w) if g[r][c]==2]
    r0=min(r for r,c in cells); r1=max(r for r,c in cells)
    c0=min(c for r,c in cells); c1=max(c for r,c in cells)
    marks=[(r,c) for r in range(h) for c in range(w) if g[r][c] not in (0,2)]
    for r in range(r0,r1+1):
        left_mark=any(rr==r and cc<c0 for rr,cc in marks)
        right_mark=any(rr==r and cc>c1 for rr,cc in marks)
        if not left_mark:
            for c in range(c0):
                if g[r][c]==0: g[r][c]=2
        if not right_mark:
            for c in range(c1+1,w):
                if g[r][c]==0: g[r][c]=2
    for c in range(c0,c1+1):
        above_mark=any(cc==c and rr<r0 for rr,cc in marks)
        below_mark=any(cc==c and rr>r1 for rr,cc in marks)
        if not above_mark:
            for r in range(r0):
                if g[r][c]==0: g[r][c]=2
        if not below_mark:
            for r in range(r1+1,h):
                if g[r][c]==0: g[r][c]=2
    return g
