def scene(h,w,rect,marks,color=8):
    g=[[0]*w for _ in range(h)]
    r0,r1,c0,c1=rect
    for r in range(r0,r1+1):
        for c in range(c0,c1+1): g[r][c]=2
    for r,c in marks:g[r][c]=color
    return g
def add_expected(g, row_sides, col_sides):
    out=[row[:] for row in g]
    # row_sides maps row -> list of inclusive extension intervals
    for r, intervals in row_sides.items():
        for a,b in intervals:
            for c in range(a,b+1):
                if out[r][c]==0:out[r][c]=2
    for c, intervals in col_sides.items():
        for a,b in intervals:
            for r in range(a,b+1):
                if out[r][c]==0:out[r][c]=2
    return out
